//! 📌️ A genuine issued field remains the same original after its root caller closes.
use crate::{RetainedCloneSource,RetainedCloneGrant,RetainedCloneProgress,RetainedOwnedProjection,RetirementDemand,observe_retirement_allocations};
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=4096);RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn source(value:Vec<String>)->RetainedCloneSource<Vec<String>>{let d=RetainedCloneSource::<Vec<String>>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(value,(),grant(RetirementDemand{copy_bytes:RetainedCloneSource::<Vec<String>>::constructor_copy_bytes(),capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})).unwrap_or_else(|_|panic!("original fixture source admission")).0}
fn close_source(owner:&mut RetainedCloneSource<Vec<String>>){for _ in 0..10000{if owner.terminal_is_empty(){return;}let g=grant(owner.next_close_demand(4096).unwrap());let(s,h)=observe_retirement_allocations(||owner.close_step(g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}panic!("original root did not close");}
#[test]
fn retained_issued_row_reference_preserves_original_pointer_path_and_paid_close(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let rank=law["selected"].as_u64().unwrap()as usize;
 for root_first in law["rootFirst"].as_array().unwrap(){let rows=law["rows"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().to_owned()).collect();let mut root=source(rows);let mut foreign=source(vec!["foreign".into()]);let row=root.borrow().project(rank,|rows|&rows[rank]);let pointer=row.get().as_ptr();let identity=row.source_identity();let d=RetainedOwnedProjection::<String>::constructor_demand();let g=grant(d);
  for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{let(result,h)=observe_retirement_allocations(||row.retain_owned(denied));assert!(result.is_err());assert_eq!(h,(0,0));}
  let((mut retained,p),h)=observe_retirement_allocations(||row.retain_owned(g).unwrap());assert!(p.fits(g));assert_eq!(h,(0,0));assert!(retained.matches_source(row));assert!(!retained.matches_source(foreign.borrow().project(0,|v|&v[0])));assert_eq!(retained.borrow().unwrap().source_identity(),identity);
  if root_first.as_bool().unwrap(){close_source(&mut root);}assert_eq!(retained.borrow().unwrap().get().as_ptr(),pointer);assert_eq!(retained.borrow().unwrap().get().as_str(),law["retained"].as_str().unwrap());
  for _ in 0..10000{if retained.terminal_is_empty(){break;}let d=retained.close_demand(4096).unwrap();let g=grant(d);for denied in[RetainedCloneGrant{maximum_items:0,..g},RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g},RetainedCloneGrant{maximum_capacity_bytes:0,..g},RetainedCloneGrant{maximum_release_bytes:0,..g},RetainedCloneGrant{maximum_depth:0,..g}]{if crate::retained_clone_grant_admits(denied,d){continue;}let(result,h)=observe_retirement_allocations(||retained.close_step(denied));let p=match result{Ok(step)=>step.progress(),Err(error)=>error.retained_progress()};assert_eq!(p,RetainedCloneProgress::default());assert_eq!(h,(0,0));assert_eq!(retained.close_demand(4096).unwrap(),d);}let(s,h)=observe_retirement_allocations(||retained.close_step(g).unwrap());assert!(s.progress().fits(g));assert_eq!(h,(s.progress().retained_capacity_bytes,s.progress().released_bytes));}assert!(retained.terminal_is_empty());assert!(retained.borrow().is_err());assert_eq!(observe_retirement_allocations(||drop(retained)).1,(0,0));close_source(&mut root);close_source(&mut foreign);
 }
}
